        return False

    # Dictionaries for forward and reverse mappings
    char_to_word = {}
    word_to_char = {}

    # Iterate through the pattern and words
    for char, word in zip(pattern, words):
        if char in char_to_word:
            # Ensure the existing mapping matches the current pair
            if char_to_word[char] != word:
                return False
        else:
            # Add the new mapping to both dictionaries
