        name = device["name"]
        primary_ip = device["primary_ip"]
        networks = device["networks"]

        # Check if the primary IP is already used by another device
        if primary_ip in used_ips:
            results[name] = False
            continue

        # Add the primary IP to the set of used IPs
        used_ips.add(primary_ip)

        # Create an IP address object from the primary IP
        try:
            ip_obj = ipaddress.ip_address(primary_ip)
        except ValueError:
            results[name] = False
            continue

        # Check if the primary IP belongs to any of the specified networks
