def mostFrequentEven(nums):
    # Filter out the even numbers from the list
    even_nums = [num for num in nums if num % 2 == 0]

    # If there are no even numbers, return -1
    if not even_nums:
        return -1

    # Create a dictionary to count the frequency of each even number
    freq_dict = {}
    for num in even_nums:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Find the maximum frequency
    max_freq = max(freq_dict.values())

    # Collect all even numbers that have the maximum frequency
    max_freq_evens = [num for num, freq in freq_dict.items() if freq == max_freq]

    # Return the smallest even number among those with the maximum frequency
    return min(max_freq_evens)

