    print(efficient_cocktail_shaker_sort([3, 0, 2, 5, -1, 4, 1]))  # Output: [-1, 0, 1, 2, 3, 4, 5]
    print(efficient_cocktail_shaker_sort([5, 1, 4, 2, 8]))         # Output: [1, 2, 4, 5, 8]
    print(efficient_cocktail_shaker_sort([]))                      # Output: []
